{
  "correction_rules": [
    "Adjust forecasts downward if model consistently overestimates prices in the short term (0-7 days) after recent spikes.",
    "Apply mean reversion bias: if forecast exceeds 2 standard deviations above recent 14-day average, reduce by 10-15%.",
    "Reduce forecast magnitude if sentiment history is flat (0.00) and true outcome shows downward drift.",
    "Increase forecast sensitivity to recent low prices if model has overcorrected upward after a dip.",
    "For horizon > 14 days, apply lag correction: if true outcome is below forecast, reduce forecast by 5-8% for next period.",
    "Avoid overshoot after spikes: if model forecast exceeds true outcome by >10% in 3-5 days, apply decay factor of 0.85 to next forecast."
  ]
}
